// Refuse to publish anything we cannot vouch for.
//
// The trap this exists for: `src/wasm/` is gitignored and generated by
// `just wasm` (cargo -> wasm-bindgen -> wasm-opt). This package's own build
// only *copies* it. So `npm publish` from a fresh checkout, or after editing
// Rust without rebuilding, ships a missing or stale binary -- and `npm pack`
// reports success either way. Every check below fails loudly instead, and
// none of them fixes anything: a publish that quietly rebuilds is a publish
// whose output nobody reviewed.
import { execFileSync } from 'node:child_process';
import { readdirSync, statSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const pkgDir = join(dirname(fileURLToPath(import.meta.url)), '..');
const repoRoot = join(pkgDir, '..', '..');

const problems = [];
const fail = (what, fix) => problems.push({ what, fix });

/** stat, or null when absent — absence is a finding, not an exception. */
const statOr = (p) => {
  try {
    return statSync(p);
  } catch {
    return null;
  }
};

// 1. The artifacts a consumer actually imports.
const required = ['dist/index.js', 'dist/index.d.ts', 'dist/wasm/bterm_wasm_bg.wasm'];
for (const rel of required) {
  if (!statOr(join(pkgDir, rel))) {
    fail(`${rel} is missing`, 'just build');
  }
}

// 2. A truncated or placeholder .wasm is the failure mode that looks fine.
//    The real binary is ~470 KB; anything under 100 KB is not it.
const wasm = statOr(join(pkgDir, 'dist/wasm/bterm_wasm_bg.wasm'));
if (wasm && wasm.size < 100_000) {
  fail(
    `dist/wasm/bterm_wasm_bg.wasm is only ${wasm.size} bytes, which is far too small to be the real binary`,
    'just build',
  );
}

// 3. The stale check, and the reason this script exists: TypeScript built
//    against different Rust than the .wasm beside it. Compare the binary's
//    mtime against every Rust source in the workspace.
if (wasm) {
  const newestRust = { path: null, mtimeMs: 0 };
  const walk = (dir) => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const full = join(dir, entry.name);
      if (entry.isDirectory()) {
        if (entry.name !== 'target' && entry.name !== 'node_modules') walk(full);
      } else if (entry.name.endsWith('.rs') || entry.name === 'Cargo.toml') {
        const s = statOr(full);
        if (s && s.mtimeMs > newestRust.mtimeMs) {
          newestRust.mtimeMs = s.mtimeMs;
          newestRust.path = full;
        }
      }
    }
  };
  walk(join(repoRoot, 'crates'));

  if (newestRust.path && newestRust.mtimeMs > wasm.mtimeMs) {
    fail(
      `${relative(repoRoot, newestRust.path)} is newer than the built .wasm, ` +
        `so the shipped binary predates the Rust source`,
      'just build',
    );
  }
}

// 4. A tarball built from a dirty tree cannot be reproduced from any commit.
try {
  const dirty = execFileSync('git', ['status', '--porcelain'], {
    cwd: repoRoot,
    encoding: 'utf8',
  }).trim();
  if (dirty) {
    const files = dirty.split('\n').slice(0, 5).join('\n  ');
    const more = dirty.split('\n').length > 5 ? '\n  …' : '';
    fail(`the working tree has uncommitted changes:\n  ${files}${more}`, 'commit or stash them');
  }
} catch {
  fail('could not read git status', 'run this from inside the repository');
}

if (problems.length > 0) {
  console.error(`\nRefusing to publish — ${problems.length} problem(s):\n`);
  for (const { what, fix } of problems) {
    console.error(`  ✗ ${what}`);
    console.error(`    fix: ${fix}\n`);
  }
  process.exit(1);
}

console.log('publishable: dist is complete, built after the Rust source, and the tree is clean');
